      var pb = document.getElementById('pbOverlay');
      var lock =
        (sheet && sheet.classList.contains('is-open')) ||
        (day && day.classList.contains('open')) ||
        (email && email.classList.contains('open')) ||
        (menu && menu.classList.contains('open')) ||
        (pb && pb.classList.contains('open'));
      document.body.style.overflow = lock ? 'hidden' : '';
    };

    /** Place Details (fetchFields) — מטמון shared 45 יום ב־matay-gmaps-frugal.js (פחות קריאות ל־Places). */
    function readPlaceSheetCache(placeId) {
      return window.MatayGmapsFrugal ? MatayGmapsFrugal.readPlacePayload(placeId) : null;
    }

    function writePlaceSheetCache(placeId, payload) {
      if (window.MatayGmapsFrugal) MatayGmapsFrugal.writeFull(placeId, payload);
    }

    /** כרטיסי אטרקציות זלצבורג: מטמון + טעינה רק בקרבת מסך (matay-gmaps-frugal.js). */
    function hydrateSalzburgAttractionThumbs() {
      if (!window.MatayGmapsFrugal) return;
      var root = document.getElementById('salzburg-attractions');
      if (!root) return;
      MatayGmapsFrugal.hydrateGooglePlaceThumbs({
        root: root,
        selector: 'img.attraction-card__thumb[data-google-place-id]'
      });
    }

    function mapEscAttr(s) {
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }
    function mapEscHtml(s) {
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    }
    function getPrimaryPlaceIdForMap(d) {
      var pe = getPlaceEntries(d);
      if (pe.length && pe[0].placeId) return pe[0].placeId;
      return d.placeId || null;
    }
    function getCachedPhotoUriForDay(d) {
      var pid = getPrimaryPlaceIdForMap(d);
      if (!pid) return '';
      var c = readPlaceSheetCache(pid);
      return c && c.photoURI ? c.photoURI : '';
    }
    function tripMapPopupHtml(d) {
      var pe = getPlaceEntries(d);
      var thumb = getCachedPhotoUriForDay(d);
      var mediaBlock;
      if (thumb) {
        mediaBlock =
          '<div class="trip-map-popup__media"><img class="trip-map-popup__img" src="' +
          mapEscAttr(thumb) +
          '" alt="" loading="lazy" decoding="async"/></div>';
      } else {
        mediaBlock =
          '<div class="trip-map-popup__media trip-map-popup__media--ph" style="background:linear-gradient(165deg,' +
          mapEscAttr(d.color) +
          ' 0%,#F5EDD8 55%,#FDF8F2 100%)"><span class="trip-map-popup__ph-emoji">' +
          d.emoji +
          '</span></div>';
      }
      var placeRow = '';
      if (pe.length) {
        placeRow =
          '<button type="button" class="trip-map-popup__link" onclick="event.preventDefault();event.stopPropagation();if(window.openPlaceSheetForDayId)window.openPlaceSheetForDayId(\'' +
          mapEscAttr(d.id) +
          '\')">\u05e4\u05e8\u05d8\u05d9 \u05de\u05e7\u05d5\u05dd \u05d1-Google Maps</button>';
      }
      return (
        '<div class="trip-map-popup">' +
        '<div class="trip-map-popup__drag" aria-label="\u05d2\u05e8\u05d9\u05e8\u05d4 \u05dc\u05d4\u05d6\u05d6\u05ea \u05d4\u05d7\u05dc\u05d5\u05df \u05e2\u05dc \u05d4\u05de\u05e4\u05d4">' +
        '<span class="trip-map-popup__drag-grip" aria-hidden="true"></span>' +
        '<span class="trip-map-popup__drag-text">\u05d2\u05e8\u05d9\u05e8\u05d4 \u05dc\u05d4\u05d6\u05d6\u05d4</span>' +
        '</div>' +
        mediaBlock +
        '<div class="trip-map-popup__body">' +
        '<div class="trip-map-popup__kicker">\u05d9\u05d5\u05dd ' +
        mapEscHtml(d.day) +
        ' \u00b7 ' +
        mapEscHtml(d.date) +
        '</div>' +
        '<div class="trip-map-popup__label">' +
        mapEscHtml(d.emoji + ' ' + d.label) +
        '</div>' +
        '<div class="trip-map-popup__title">' +
        mapEscHtml(d.title) +
        '</div>' +
        '<button type="button" class="trip-map-popup__btn" style="background:' +
