        '\')">\u05dc\u05e4\u05e8\u05d8\u05d9 \u05d4\u05d9\u05d5\u05dd \u05d1\u05de\u05e1\u05dc\u05d5\u05dc</button>' +
        placeRow +
        '</div></div>'
      );
