    function placeDisplayNameText(place) {
      var dn = place.displayName;
      if (dn == null) return '';
      if (typeof dn === 'string') return dn;
      if (dn.text) return dn.text;
      return String(dn);
    }

    function applyPlacePayloadToSheet(payload, day) {
      var titleEl = document.getElementById('placeSheetTitle');
      var summaryEl = document.getElementById('placeSheetSummary');
      var photoEl = document.getElementById('placeSheetPhoto');
      var mapsLink = document.getElementById('placeSheetMapsLink');
      var phoneEl = document.getElementById('placeSheetPhone');
      var phoneLabelEl = document.getElementById('placeSheetPhoneLabel');
      var webEl = document.getElementById('placeSheetWeb');

      titleEl.textContent = payload.displayName || day.title;

      if (payload.editorialSummary) {
        summaryEl.textContent = payload.editorialSummary;
        summaryEl.hidden = false;
      } else {
        summaryEl.hidden = true;
        summaryEl.textContent = '';
      }

      setPlaceSheetMeta('placeSheetAddress', 'placeSheetAddressText', payload.formattedAddress || '');

      if (payload.rating != null) {
        var urc = payload.userRatingCount != null ? ' (' + payload.userRatingCount + ' ביקורות)' : '';
        setPlaceSheetMeta('placeSheetRating', 'placeSheetRatingText', 'דירוג: ' + payload.rating + '\u2605' + urc);
      } else setPlaceSheetMeta('placeSheetRating', 'placeSheetRatingText', '');

      if (payload.weekdayDescriptions && payload.weekdayDescriptions.length) {
        setPlaceSheetMeta('placeSheetHours', 'placeSheetHoursText', payload.weekdayDescriptions.join(' · '));
      } else setPlaceSheetMeta('placeSheetHours', 'placeSheetHoursText', '');

      mapsLink.href = payload.googleMapsURI || 'https://www.google.com/maps?q=' + day.lat + ',' + day.lng;

      var phone = payload.nationalPhoneNumber || payload.internationalPhoneNumber;
      if (phone) {
        phoneEl.hidden = false;
        if (phoneLabelEl) phoneLabelEl.textContent = phone;
        phoneEl.href = 'tel:' + String(phone).replace(/\s/g, '');
      } else {
        phoneEl.hidden = true;
        if (phoneLabelEl) phoneLabelEl.textContent = '';
      }

      if (payload.websiteURI) {
        webEl.hidden = false;
        webEl.href = payload.websiteURI;
      } else webEl.hidden = true;

      if (payload.photoURI) {
        photoEl.src = payload.photoURI;
        photoEl.hidden = false;
      } else {
        photoEl.hidden = true;
        photoEl.removeAttribute('src');
      }
    }

    function buildPayloadFromPlace(place, day) {
      var oh = place.regularOpeningHours || place.openingHours;
      var weekdayDescriptions =
        oh && oh.weekdayDescriptions && oh.weekdayDescriptions.length ? oh.weekdayDescriptions.slice() : null;
      var photoURI = null;
      if (place.photos && place.photos.length && typeof place.photos[0].getURI === 'function') {
        try {
          photoURI = place.photos[0].getURI({ maxWidth: 1280, maxHeight: 800 }) || null;
        } catch (e) {
          photoURI = null;
        }
      }
      return {
        displayName: placeDisplayNameText(place) || day.title,
        formattedAddress: place.formattedAddress || '',
        rating: place.rating != null ? place.rating : null,
        userRatingCount: place.userRatingCount != null ? place.userRatingCount : null,
        editorialSummary:
          place.editorialSummary && place.editorialSummary.text ? place.editorialSummary.text : '',
        weekdayDescriptions: weekdayDescriptions,
        googleMapsURI: place.googleMapsURI || '',
        nationalPhoneNumber: place.nationalPhoneNumber || '',
        internationalPhoneNumber: place.internationalPhoneNumber || '',
        websiteURI: place.websiteURI || '',
        photoURI: photoURI
      };
    }

    function setPlaceSheetMeta(rowId, textId, value) {
      var row = document.getElementById(rowId);
      var span = document.getElementById(textId);
      if (!row || !span) return;
      var t = value == null ? '' : String(value);
      span.textContent = t;
      row.hidden = !t;
    }

    function closePlaceSheet() {
      var root = document.getElementById('placeSheet');
      if (!root) return;
      root.classList.remove('is-open');
      root.setAttribute('aria-hidden', 'true');
      _placeSheetDay = null;
      window.__mtRefreshBodyScrollLock();
    }

    function openPlaceSheet(day, subIndex) {
      subIndex = subIndex || 0;
      var root = document.getElementById('placeSheet');
      if (!root) return;
      var entries = getPlaceEntries(day);
      var pillsEl = document.getElementById('placeSheetPills');
      var mapsLink = document.getElementById('placeSheetMapsLink');
      mapsLink.href = 'https://www.google.com/maps?q=' + day.lat + ',' + day.lng;

      if (!entries.length) {
        document.getElementById('placeSheetTitle').textContent = day.title || '';
        setPlaceSheetMeta('placeSheetAddress', 'placeSheetAddressText', '');
        setPlaceSheetMeta('placeSheetRating', 'placeSheetRatingText', '');
        setPlaceSheetMeta('placeSheetHours', 'placeSheetHoursText', '');
        document.getElementById('placeSheetSummary').hidden = true;
        document.getElementById('placeSheetPhoto').hidden = true;
        document.getElementById('placeSheetPhone').hidden = true;
        var _plEmpty = document.getElementById('placeSheetPhoneLabel');
        if (_plEmpty) _plEmpty.textContent = '';
        document.getElementById('placeSheetWeb').hidden = true;
        pillsEl.hidden = true;
        pillsEl.innerHTML = '';
        root.classList.add('is-open');
        root.setAttribute('aria-hidden', 'false');
        window.__mtRefreshBodyScrollLock();
        return;
      }

      _placeSheetDay = day;
      pillsEl.innerHTML = '';
      if (entries.length > 1) {
        pillsEl.hidden = false;
        entries.forEach(function(ent, i) {
          var b = document.createElement('button');
          b.type = 'button';
          b.className = 'place-sheet__pill' + (i === subIndex ? ' is-active' : '');
          b.textContent = ent.label || ('מקום ' + (i + 1));
          b.addEventListener('click', function() {
            openPlaceSheet(day, i);
          });
          pillsEl.appendChild(b);
        });
      } else {
        pillsEl.hidden = true;
      }

      root.classList.add('is-open');
      root.setAttribute('aria-hidden', 'false');
      window.__mtRefreshBodyScrollLock();

      var key = (window.GOOGLE_MAPS_API_KEY || '').trim();
      if (!key) {
        document.getElementById('placeSheetTitle').textContent = entries[subIndex].label || day.title;
        setPlaceSheetMeta(
          'placeSheetAddress',
          'placeSheetAddressText',
          ''
        );
        setPlaceSheetMeta('placeSheetRating', 'placeSheetRatingText', '');
        setPlaceSheetMeta('placeSheetHours', 'placeSheetHoursText', '');
        document.getElementById('placeSheetSummary').hidden = true;
        document.getElementById('placeSheetPhoto').hidden = true;
        document.getElementById('placeSheetPhone').hidden = true;
        var _plKey = document.getElementById('placeSheetPhoneLabel');
        if (_plKey) _plKey.textContent = '';
        document.getElementById('placeSheetWeb').hidden = true;
        return;
      }
      if (!window.google || !google.maps) {
        if (window.MatayGmapsFrugal) {
          window.MatayGmapsFrugal.ensureGoogleMaps(function () {
            openPlaceSheet(day, subIndex);
          });
        } else {
          document.getElementById('placeSheetTitle').textContent = entries[subIndex].label || day.title;
          setPlaceSheetMeta(
            'placeSheetAddress',
            'placeSheetAddressText',
            'טוען את ספריית המפות… רעננו את הדף אם זה נמשך.'
          );
          setPlaceSheetMeta('placeSheetRating', 'placeSheetRatingText', '');
          setPlaceSheetMeta('placeSheetHours', 'placeSheetHoursText', '');
          document.getElementById('placeSheetSummary').hidden = true;
          document.getElementById('placeSheetPhoto').hidden = true;
          document.getElementById('placeSheetPhone').hidden = true;
          var _plKey2 = document.getElementById('placeSheetPhoneLabel');
          if (_plKey2) _plKey2.textContent = '';
          document.getElementById('placeSheetWeb').hidden = true;
        }
        return;
      }

      loadPlaceIntoSheet(entries[subIndex].placeId, day);
    }

    function loadPlaceIntoSheet(placeId, day) {
      var cached = readPlaceSheetCache(placeId);
      if (cached) {
        applyPlacePayloadToSheet(cached, day);
        return;
      }

      var titleEl = document.getElementById('placeSheetTitle');
      var summaryEl = document.getElementById('placeSheetSummary');
      var photoEl = document.getElementById('placeSheetPhoto');
      var mapsLink = document.getElementById('placeSheetMapsLink');
      var phoneEl = document.getElementById('placeSheetPhone');
      var phoneLabelEl = document.getElementById('placeSheetPhoneLabel');
      var webEl = document.getElementById('placeSheetWeb');

      titleEl.textContent = 'טוען…';
      summaryEl.hidden = true;
      summaryEl.textContent = '';
      setPlaceSheetMeta('placeSheetAddress', 'placeSheetAddressText', '');
      setPlaceSheetMeta('placeSheetRating', 'placeSheetRatingText', '');
      setPlaceSheetMeta('placeSheetHours', 'placeSheetHoursText', '');
      photoEl.hidden = true;
      photoEl.removeAttribute('src');
      phoneEl.hidden = true;
      if (phoneLabelEl) phoneLabelEl.textContent = '';
      webEl.hidden = true;
      mapsLink.href = 'https://www.google.com/maps?q=' + day.lat + ',' + day.lng;

      google.maps
        .importLibrary('places')
        .then(function(lib) {
          var Place = lib.Place;
          var place = new Place({ id: placeId });
          return place.fetchFields({
            fields: [
              'displayName',
              'formattedAddress',
              'rating',
              'userRatingCount',
              'nationalPhoneNumber',
              'internationalPhoneNumber',
              'websiteURI',
              'regularOpeningHours',
              'googleMapsURI',
              'photos',
              'editorialSummary'
            ]
          }).then(function() {
            return place;
          });
        })
        .then(function(place) {
          var payload = buildPayloadFromPlace(place, day);
          applyPlacePayloadToSheet(payload, day);
          writePlaceSheetCache(placeId, payload);
        })
        .catch(function(err) {
          titleEl.textContent = 'לא ניתן לטעון פרטי מקום';
          var host = (typeof location !== 'undefined' && location.hostname) ? location.hostname : '';
          var hints = [];
          if (host === 'localhost' || host === '127.0.0.1' || !host || location.protocol === 'file:') {
            hints.push('מפתח עם HTTP referrer מוגבל לא יעבוד מ-file:// או מ-localhost. פתחו את הדף ב-https://mataytasim.co.il/ (אחרי העלאה) או הוסיפו referrer לפיתוח: http://localhost:*/*');
          } else if (host.indexOf('mataytasim.co.il') !== -1) {
            hints.push('ב-API key → Application restrictions: הוסיפו גם https://mataytasim.co.il/* וגם https://www.mataytasim.co.il/* (עם https).');
          }
