    var tripRouteGroup = L.layerGroup().addTo(map);
    /** ימים שמציגים קווים + חצים במפה (סדר כרונולוגי). tl1 בלי מסלול; tl9–tl10 בלי חיבור מ-Hornergut */
    var TRIP_ROUTE_DRAW_ORDER = ['tl2', 'tl3', 'tl4', 'tl5', 'tl6', 'tl7', 'tl8', 'tl9', 'tl10'];

    function getDayRoutePath(d) {
      if (d.routePath && d.routePath.length) return d.routePath;
      return [[d.lat, d.lng]];
    }

    function bearingDeg(a, b) {
      var la1 = (a[0] * Math.PI) / 180;
      var la2 = (b[0] * Math.PI) / 180;
      var dLo = ((b[1] - a[1]) * Math.PI) / 180;
      var y = Math.sin(dLo) * Math.cos(la2);
      var x =
        Math.cos(la1) * Math.sin(la2) - Math.sin(la1) * Math.cos(la2) * Math.cos(dLo);
      return (Math.atan2(y, x) * 180) / Math.PI;
    }

    function interpLL(a, b, t) {
      return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
    }

    var TRIP_ROUTE_LINE_COLOR = '#2fb8a8';
    function addMapRouteSegment(a, b) {
      L.polyline([a, b], {
        className: 'trip-route-path',
        color: TRIP_ROUTE_LINE_COLOR,
        weight: 4,
        opacity: 0.7,
        lineCap: 'round',
        lineJoin: 'round',
        interactive: false
      }).addTo(tripRouteGroup);
      var mid = interpLL(a, b, 0.52);
      var brng = bearingDeg(a, b);
      var rot = brng - 90;
      L.marker(mid, {
        interactive: false,
        keyboard: false,
        icon: L.divIcon({
          className: 'trip-route-arrow-wrap',
          html:
            '<div class="trip-route-arrow-rot" style="transform:rotate(' +
            rot +
            'deg)">' +
            '<svg class="trip-route-arrow-svg" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' +
            '<path d="M5 4 L19 12 L5 20 Z" fill="#1a7a6e" stroke="#ffffff" stroke-width="1.5" stroke-linejoin="round"/>' +
            '</svg></div>',
          iconSize: [26, 26],
          iconAnchor: [13, 13]
        })
      }).addTo(tripRouteGroup);
    }

    function drawAllTripRoutes() {
      var byId = {};
      days.forEach(function(d) {
        byId[d.id] = d;
      });
      var home = hornergutLL();
      TRIP_ROUTE_DRAW_ORDER.forEach(function(id) {
        var d = byId[id];
        if (!d) return;
        var path = getDayRoutePath(d);
        if (!path || !path.length) return;
        if (!d.routeSkipHornergut && id !== 'tl1') {
          addMapRouteSegment(home, path[0]);
        }
        for (var j = 0; j < path.length - 1; j++) {
          addMapRouteSegment(path[j], path[j + 1]);
        }
      });
    }

    function formatDriveDurationHe(totalMins) {
      if (totalMins < 60) return '\u05db\u2009' + totalMins + ' \u05d3\u05e7\u05f3';
      var h = Math.floor(totalMins / 60);
      var m = totalMins % 60;
      if (m === 0) {
        if (h === 1) return '\u05db\u2009\u05e9\u05e2\u05d4';
        if (h === 2) return '\u05db\u2009\u05e9\u05ea\u05d9\u05d9\u05dd';
        return '\u05db\u2009' + h + ' \u05e9\u05e2\u05d5\u05ea';
      }
      if (h === 1) return '\u05db\u2009\u05e9\u05e2\u05d4 \u05d5\u2013' + m + ' \u05d3\u05e7\u05f3';
      if (h === 2) return '\u05db\u2009\u05e9\u05ea\u05d9\u05d9\u05dd \u05d5\u2013' + m + ' \u05d3\u05e7\u05f3';
      return '\u05db\u2009' + h + ' \u05e9\u05e2\u05d5\u05ea \u05d5\u2013' + m + ' \u05d3\u05e7\u05f3';
    }

