    /** Drag the popup card on the map (handle bar) - cleanup on popupclose. */
    function attachTripMapPopupDrag(marker) {
      var popup = marker.getPopup();
      if (!popup) return;
      var root = popup.getElement();
      if (!root) return;
      var inner = root.querySelector('.trip-map-popup');
      var handle = root.querySelector('.trip-map-popup__drag');
      if (!inner || !handle) return;
      if (marker._tripMapDragDispose) {
        marker._tripMapDragDispose();
        marker._tripMapDragDispose = null;
      }
      inner.style.transform = '';
      var ox = 0;
      var oy = 0;
      var dragging = false;
      var startX = 0;
      var startY = 0;
      var origOx = 0;
      var origOy = 0;
      function clientXY(e) {
        if (e.touches && e.touches.length) return [e.touches[0].clientX, e.touches[0].clientY];
        return [e.clientX, e.clientY];
      }
      function onDown(e) {
        if (e.type === 'mousedown' && e.button !== 0) return;
        dragging = true;
        var p = clientXY(e);
        startX = p[0];
        startY = p[1];
        origOx = ox;
        origOy = oy;
        if (e.type === 'touchstart') e.preventDefault();
      }
      function onMove(e) {
        if (!dragging) return;
        var p = clientXY(e);
        ox = origOx + (p[0] - startX);
        oy = origOy + (p[1] - startY);
        inner.style.transform = 'translate(' + ox + 'px,' + oy + 'px)';
        if (e.type === 'touchmove') e.preventDefault();
      }
      function onUp() {
        dragging = false;
      }
      handle.addEventListener('mousedown', onDown);
      handle.addEventListener('touchstart', onDown, { passive: false });
      document.addEventListener('mousemove', onMove);
      document.addEventListener('touchmove', onMove, { passive: false });
      document.addEventListener('mouseup', onUp);
      document.addEventListener('touchend', onUp);
      marker._tripMapDragDispose = function() {
        handle.removeEventListener('mousedown', onDown);
        handle.removeEventListener('touchstart', onDown);
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('touchmove', onMove);
        document.removeEventListener('mouseup', onUp);
        document.removeEventListener('touchend', onUp);
        inner.style.transform = '';
      };
    }

    var markers = {};
    var activeId = null;
    var hoverMapId = null;
    var dayById = {};
    days.forEach(function(x) {
      dayById[x.id] = x;
    });

    function setHoverMapId(id) {
      var prev = hoverMapId;
      hoverMapId = id;
      if (prev && markers[prev]) markers[prev].setIcon(makeTripMapPin(dayById[prev]));
      if (hoverMapId && markers[hoverMapId]) markers[hoverMapId].setIcon(makeTripMapPin(dayById[hoverMapId]));
    }

    /** Circle + emoji (slovakia-style) + invisible padding so taps register on first try. */
    function makeTripMapPin(d) {
      var active = d.id === activeId;
      var syncHover = !active && d.id === hoverMapId;
      var inner = active ? 46 : syncHover ? 40 : 38;
      var pad = 14;
      var hit = inner + pad * 2;
      var bg = active ? d.color : '#fff';
      var border = active ? '#fff' : d.color;
      var fontSize = active ? 20 : syncHover ? 17 : 16;
      var shadow = syncHover
        ? '0 3px 12px rgba(0,0,0,0.22),0 0 0 3px rgba(26,107,114,0.35)'
        : '0 3px 12px rgba(0,0,0,0.22)';
      var disc =
        'width:' +
        inner +
        'px;height:' +
        inner +
        'px;border-radius:50%;background:' +
        bg +
        ';border:2.5px solid ' +
        border +
        ';display:flex;align-items:center;justify-content:center;font-size:' +
        fontSize +
        'px;box-shadow:' +
        shadow +
        ';cursor:pointer;-webkit-tap-highlight-color:transparent;pointer-events:auto';
      return L.divIcon({
        className: '',
        html:
          '<div style="width:' +
          hit +
          'px;height:' +
          hit +
          'px;display:flex;align-items:center;justify-content:center;-webkit-tap-highlight-color:transparent;cursor:pointer;pointer-events:auto">' +
          '<div style="' +
          disc +
          '"><span style="line-height:1;">' +
          d.emoji +
          '</span></div></div>',
        iconSize: [hit, hit],
        iconAnchor: [hit / 2, hit / 2],
        popupAnchor: [0, -(hit / 2 + 4)]
      });
    }

    function setActive(id) {
      activeId = id;
      days.forEach(function(d) {
        if (markers[d.id]) {
          markers[d.id].setIcon(makeTripMapPin(d));
          markers[d.id].setZIndexOffset(d.id === id ? 800 : 0);
        }
      });
      document.querySelectorAll('.map-pill').forEach(function(p) {
        p.style.background = p.dataset.id === id ? 'var(--teal)' : 'var(--white)';
        p.style.color = p.dataset.id === id ? '#fff' : 'var(--charcoal)';
        p.style.borderColor = p.dataset.id === id ? 'var(--teal)' : 'var(--sand-dark)';
      });
    }

    function flyTo(d) {
      map.closePopup();
      setActive(d.id);
      var w = window.innerWidth || 800;
      var latPad = w <= 600 ? 0.024 : 0.016;
      map.flyTo([d.lat + latPad, d.lng], 10, { duration: 1 });
      map.once('moveend', function() {
        if (markers[d.id]) markers[d.id].openPopup();
      });
    }

    window.goToDay = function(id) {
      map.closePopup();
      if (dayById[id]) setActive(id);
      var card = document.getElementById(id);
      if (card) {
        var tl = card.querySelector('.tl-card');
        if (tl && !tl.classList.contains('open')) toggleTl(id);
        card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    };

    /** Hover pins only with real mouse (not touch), otherwise synthetic mouseover + setIcon breaks the first tap opening the popup. */
    var tripMapPinsHoverable =
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(hover: hover) and (pointer: fine)').matches;

    days.forEach(function(d) {
      var m = L.marker([d.lat, d.lng], { icon: makeTripMapPin(d) }).bindPopup(
        tripMapPopupHtml(d),
        tripMapPopupBindOptions()
      );
      m.on('click', function() {
        setActive(d.id);
      });
      m.on('popupopen', function() {
        setActive(d.id);
        m.setPopupContent(tripMapPopupHtml(d));
        syncTripMapPopupMaxHeight();
        requestAnimationFrame(function() {
          attachTripMapPopupDrag(m);
          var pu = m.getPopup();
          if (pu && pu.update) pu.update();
        });
      });
      m.on('popupclose', function() {
        if (m._tripMapDragDispose) {
          m._tripMapDragDispose();
          m._tripMapDragDispose = null;
        }
      });
      m.on('mouseover', function() {
        if (tripMapPinsHoverable) setHoverMapId(d.id);
      });
      m.on('mouseout', function() {
        if (tripMapPinsHoverable) setHoverMapId(null);
      });
      m.addTo(map);
      markers[d.id] = m;
    });

    var pillsContainer = document.getElementById('map-day-pills');
    days.forEach(function(d) {
      var btn = document.createElement('button');
      btn.className = 'map-pill';
