    function loadOverpassPOIs(map) {
      var query =
        '[out:json][timeout:25];' +
        '(' +
        'node["amenity"~"restaurant|cafe|pub|bar|fast_food"](around:8000,47.092,13.691);' +
        'node["amenity"~"restaurant|cafe|pub|bar|fast_food"](around:5000,' +
        HORNERGUT_LAT +
        ',' +
        HORNERGUT_LNG +
        ');' +
        'node["tourism"~"attraction|viewpoint|museum"](around:8000,47.092,13.691);' +
        'node["historic"~"castle|monument|ruins|memorial"](around:8000,47.092,13.691);' +
        'node["leisure"~"park|nature_reserve|playground"](around:5000,47.092,13.691);' +
        ');out body;';
      fetch('https://overpass-api.de/api/interpreter?data=' + encodeURIComponent(query))
        .then(function(r) { return r.json(); })
        .then(function(data) {
          (data.elements || []).forEach(function(el) {
            if (!el.lat || !el.lon) return;
            var t = el.tags || {};
            var name = t.name || t['name:en'] || t['name:de'] || sub || '–';

            var emoji = '📍', bg = '#999', sub = '';
            var a = t.amenity, tour = t.tourism, hist = t.historic, lei = t.leisure;
            if (a === 'restaurant' || a === 'fast_food') { emoji = '🍽️'; bg = '#E8A045'; sub = 'מסעדה'; }
            else if (a === 'cafe')                       { emoji = '☕';  bg = '#a0522d'; sub = 'בית קפה'; }
            else if (a === 'pub' || a === 'bar')         { emoji = '🍺';  bg = '#7f5a0d'; sub = 'בר'; }
            else if (tour === 'viewpoint')               { emoji = '🌄';  bg = '#1A6B72'; sub = 'נקודת תצפית'; }
            else if (tour === 'attraction')              { emoji = '⭐';  bg = '#c0392b'; sub = 'אטרקציה'; }
            else if (tour === 'museum')                  { emoji = '🏛️'; bg = '#5b4fcf'; sub = 'מוזיאון'; }
            else if (tour === 'hotel' || tour === 'guest_house' || tour === 'hostel') { emoji = '🏨'; bg = '#1A6B72'; sub = 'לינה'; }
            else if (hist === 'castle' || hist === 'ruins') { emoji = '🏰'; bg = '#6b4aa0'; sub = 'טירה / עתיקות'; }
