        }
      });
    }

    function emailOverlayOpen() {
      var el = document.getElementById('emailPopupOverlay');
      return el && el.classList.contains('open');
    }
    function lockScroll(lock) {
      if (lock) { if (!emailOverlayOpen()) document.body.style.overflow = 'hidden'; }
      else { if (!emailOverlayOpen()) document.body.style.overflow = ''; }
    }
    function getFocusables() {
      var nodes = dialog.querySelectorAll('a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])');
      return Array.prototype.slice.call(nodes).filter(function (n) {
        if (n.disabled) return false;
        var st = window.getComputedStyle(n);
        return st.visibility !== 'hidden' && st.display !== 'none';
      });
    }
    function trapKeydown(e) {
      if (e.key !== 'Tab' || !root.classList.contains('is-open')) return;
      var list = getFocusables();
      if (!list.length) return;
      var first = list[0];
      var last = list[list.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
    function openDrawer() {
      prevFocus = document.activeElement;
      root.hidden = false;
      requestAnimationFrame(function () {
        root.classList.add('is-open');
        lockScroll(true);
        openedAt = Date.now();
        openBtn.setAttribute('aria-expanded', 'true');
        if (window.plausible) { try { plausible('GoodToKnow-Open', { props: { country: countryKey } }); } catch (ex) {} }
        if (closeBtn) closeBtn.focus();
      });
    }
    function closeDrawer() {
      root.classList.remove('is-open');
      lockScroll(false);
      openBtn.setAttribute('aria-expanded', 'false');
      var t = prevFocus;
      prevFocus = null;
      if (t && typeof t.focus === 'function') t.focus();
      window.setTimeout(function () { if (!root.classList.contains('is-open')) root.hidden = true; }, 320);
    }
    openBtn.addEventListener('click', openDrawer);
    if (closeBtn) closeBtn.addEventListener('click', closeDrawer);
    if (backdrop) backdrop.addEventListener('click', function () { if (Date.now() - openedAt > 350) closeDrawer(); });
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'Escape' || !root.classList.contains('is-open')) return;
      e.preventDefault();
      closeDrawer();
    }, true);
    dialog.addEventListener('keydown', trapKeydown);
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState === 'hidden' && root.classList.contains('is-open')) closeDrawer();
    });
  })();

